    return this.client.get<AllContentRecordTypes>(`deployments/${encodedId}`, {
      params: {
        dir,
      },
    });
  }

  // Returns:
  // 200 - success
  // 400 - bad request
  // 409 - conflict
  // 500 - internal server error
  // Errors returned through event stream
  createNew(
    dir: string,
    accountName?: string,
    configName?: string,
    saveName?: string,
  ) {
    const data = {
      account: accountName,
      config: configName,
      saveName,
    };
    return this.client.post<PreContentRecord>("/deployments", data, {
      params: { dir },
    });
  }

